"1" class=""/><text x="24" y="150" class="ss" text-anchor="start" font-size="12" font-weight="normal">Location *</text><rect x="24" y="158" width="334" height="30" rx="4" fill="var(--card)" stroke="var(--line)" stroke-width="1" class=""/><text x="24" y="210" class="ss" text-anchor="start" font-size="12" font-weight="normal">Document Library *</text><rect x="24" y="218" width="334" height="30" rx="4" fill="var(--card)" stroke="var(--line)" stroke-width="1" class=""/><text x="24" y="270" class="ss" text-anchor="start" font-size="12" font-weight="normal">File *</text><rect x="24" y="278" width="334" height="30" rx="4" fill="var(--card)" stroke="var(--line)" stroke-width="1" class=""/><text x="24" y="330" class="ss" text-anchor="start" font-size="12" font-weight="normal">Table *</text><rect x="24" y="338" width="334" height="30" rx="4" fill="var(--card)" stroke="var(--line)" stroke-width="1" class=""/><text x="24" y="410" class="ss" text-anchor="start" font-size="12" font-weight="normal">（Parameters タブでは設定する項目が並びます）</text><rect x="520" y="56" width="190" height="44" rx="5" fill="#0f6cbd" stroke="none" stroke-width="1" class=""/><text x="615.0" y="83.0" class="sw" text-anchor="middle" font-size="14" font-weight="bold">Manually trigger a flow</text><line x1="615" y1="100" x2="615" y2="128" stroke="var(--sub)" stroke-width="2" marker-end="url(#ahbn)"/><rect x="470" y="128" width="290" height="150" rx="6" fill="var(--bg)" stroke="#8c3a00" stroke-width="2" class=""/><rect x="470" y="128" width="290" height="28" rx="6" fill="#8c3a00" stroke="none" stroke-width="1" class=""/><text x="484" y="147" class="sw" text-anchor="start" font-size="14" font-weight="bold">Try</text><rect x="500" y="176" width="230" height="52" rx="5" fill="#107c41" stroke="var(--acc)" stroke-width="4" class=""/><text x="615" y="207" class="sw" text-anchor="middle" font-size="13" font-weight="bold">List rows present in a table</text><line x1="615" y1="278" x2="615" y2="300" stroke="var(--sub)" stroke-width="2" marker-end="url(#ahbn)"/><rect x="520" y="300" width="190" height="44" rx="5" fill="#5f6b7a" stroke="none" stroke-width="1" class=""/><text x="615.0" y="327.0" class="sw" text-anchor="middle" font-size="14" font-weight="bold">Apply to each</text><circle cx="640" cy="177" r="13" fill="var(--warn)"/><text x="640" y="182" text-anchor="middle" font-size="14" font-weight="bold" fill="#fff">1</text><text x="500" y="250" class="sw2" text-anchor="start" font-size="12" font-weight="bold">① 取りたい箱を1回クリック（青い枠が付く）</text><path d="M 224 100 C 224 82, 250 82, 250 90" fill="none" stroke="var(--warn)" stroke-width="0.1" marker-end="url(#ahbw)"/><circle cx="215" cy="90" r="13" fill="var(--warn)"/><text x="215" y="95" text-anchor="middle" font-size="14" font-weight="bold" fill="#fff">2</text><text x="395" y="372" class="sw2" text-anchor="start" font-size="13" font-weight="bold">② 左のパネルの「Code view」タブをクリック</text><text x="395" y="393" class="sw2" text-anchor="start" font-size="13" font-weight="bold">③ 出てきた文字の中をクリック</text><text x="395" y="414" class="sw2" text-anchor="start" font-size="13" font-weight="bold">    → Ctrl＋A（全部選ぶ）→ Ctrl＋C（コピー）</text><text x="395" y="435" class="sw2" text-anchor="start" font-size="13" font-weight="bold">④ 伏字ツールに貼り付ける</text><text x="395" y="480" class="ss" text-anchor="start" font-size="12" font-weight="normal">※ ページ分け・並列実行などの設定は「Settings」タブにあります</text></svg><figcaption>画面の見取り図：コードの取り出しはここ（Code view タブ）</figcaption></figure>
'@
